body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 32px; }

.cart-count {
  background-color: #2563eb;
  color: #ffffff;
  border-radius: 999px;
  padding: 2px 10px;
}

.product-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 768px) {
  .product-grid { grid-template-columns: 1fr 1fr 1fr; }
}

.product-card {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
}

.btn-add {
  background-color: #2563eb;
  color: #ffffff;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}

import React, { useState } from "react";
import { createRoot } from "react-dom/client";

const products = [
  { id: 1, name: "Монгол дээл", price: 129000 },
  { id: 2, name: "Малгай", price: 45000 },
  { id: 3, name: "Гутал", price: 89000 },
];

function ProductCard({ name, price }) {
  return (
    <article className="product-card">
      <h3>{name}</h3>
      <p className="price">₮ {price.toLocaleString("en-US")}</p>
      <button className="btn-add" data-testid="add-to-cart">Сагсанд хийх</button>
    </article>
  );
}

function App() {
  // энд бичнэ үү

  return (
    <main>
      <h1>Shop.mn</h1>
      <section className="product-grid">
        {products.map((product) => (
          <ProductCard key={product.id} name={product.name} price={product.price} />
        ))}
      </section>
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);

