import React, { useState } from "react";
import { createRoot } from "react-dom/client";

const products = [
  { id: 1, name: "Монгол дээл", price: 129000 },
  { id: 2, name: "Малгай", price: 45000 },
  { id: 3, name: "Гутал", price: 89000 },
];

function ProductCard({ name, price, onAdd }) {
  return (
    <article className="product-card">
      <h3>{name}</h3>
      <p className="price">₮ {price.toLocaleString("en-US")}</p>
      <button className="btn-add" data-testid="add-to-cart" onClick={onAdd}>
        Сагсанд хийх
      </button>
    </article>
  );
}

function App() {
  const [count, setCount] = useState(0);

  return (
    <main>
      <h1>Shop.mn</h1>
      <span className="cart-count" data-testid="cart-count">{count}</span>
      <section className="product-grid">
        {products.map((product) => (
          <ProductCard
            key={product.id}
            name={product.name}
            price={product.price}
            onAdd={() => setCount(count + 1)}
          />
        ))}
      </section>
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);
